package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.PermissionManager;import com.bedlessfighter.necroManager.MessageManager;import org.bukkit.Bukkit;import org.bukkit.command.*;import org.bukkit.entity.Player;
public final class SetLevelCommand implements CommandExecutor{public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!PermissionManager.has(s,"necromanager.setlevel")){MessageManager.send(s,"messages.no-permission","&cYou do not have permission.");return true;}if(a.length<1||a.length>2){s.sendMessage("Usage: /setlevel <level> [player]");return true;}int n;try{n=Integer.parseInt(a[0]);}catch(NumberFormatException e){s.sendMessage("Level must be an integer.");return true;}if(n<0||n>10000){s.sendMessage("Level must be 0-10000.");return true;}Player p=a.length==2?Bukkit.getPlayerExact(a[1]):s instanceof Player?(Player)s:null;if(p==null){s.sendMessage(a.length==2?"Player is not online.":"Only players may omit the target.");return true;}p.setLevel(n);MessageManager.sendRaw(s,"&aSet "+p.getName()+"'s level to "+n+".");return true;}}
